test("returns simple interest rounded to 2 decimals when the start day is counted and the end day is excluded", function () {
  assert.deepEqual(code.simpleInterest({
    principal: 10000.00,
    annualRate: 0.06,
    startDate: "2026-03-01",
    endDate: "2026-04-01"
  }), { days: 31, interest: 50.96 });
});

test("divides by 365 in a leap year when 29 February is the last included day", function () {
  assert.deepEqual(code.simpleInterest({
    principal: 10000.00,
    annualRate: 0.06,
    startDate: "2028-02-01",
    endDate: "2028-03-01"
  }), { days: 29, interest: 47.67 });
});

test("returns zero days and zero interest when the start and end dates are equal", function () {
  assert.deepEqual(code.simpleInterest({
    principal: 10000.00,
    annualRate: 0.06,
    startDate: "2026-03-01",
    endDate: "2026-03-01"
  }), { days: 0, interest: 0.00 });
});

test("returns one day of interest for the smallest positive day count", function () {
  assert.deepEqual(code.simpleInterest({
    principal: 10000.00,
    annualRate: 0.06,
    startDate: "2026-03-01",
    endDate: "2026-03-02"
  }), { days: 1, interest: 1.64 });
});

test("counts the last day of a month when that day is the start date", function () {
  assert.deepEqual(code.simpleInterest({
    principal: 10000.00,
    annualRate: 0.06,
    startDate: "2026-03-31",
    endDate: "2026-04-01"
  }), { days: 1, interest: 1.64 });
});

test("excludes the end date when it falls on the last day of the month", function () {
  assert.deepEqual(code.simpleInterest({
    principal: 10000.00,
    annualRate: 0.04,
    startDate: "2026-03-01",
    endDate: "2026-03-31"
  }), { days: 30, interest: 32.88 });
});

test("counts December 31 and excludes January 1 across the year boundary", function () {
  assert.deepEqual(code.simpleInterest({
    principal: 10000.00,
    annualRate: 0.06,
    startDate: "2026-12-31",
    endDate: "2027-01-01"
  }), { days: 1, interest: 1.64 });
});

test("counts every day of December when the period ends on January 1", function () {
  assert.deepEqual(code.simpleInterest({
    principal: 10000.00,
    annualRate: 0.06,
    startDate: "2026-12-01",
    endDate: "2027-01-01"
  }), { days: 31, interest: 50.96 });
});

test("excludes the last day of January when that day is the end date", function () {
  assert.deepEqual(code.simpleInterest({
    principal: 10000.00,
    annualRate: 0.04,
    startDate: "2027-01-01",
    endDate: "2027-01-31"
  }), { days: 30, interest: 32.88 });
});

test("counts leap day when it is the first included day", function () {
  assert.deepEqual(code.simpleInterest({
    principal: 10000.00,
    annualRate: 0.06,
    startDate: "2028-02-29",
    endDate: "2028-03-01"
  }), { days: 1, interest: 1.64 });
});

test("counts leap day in the middle of the period and still divides by 365", function () {
  assert.deepEqual(code.simpleInterest({
    principal: 10000.00,
    annualRate: 0.06,
    startDate: "2028-02-28",
    endDate: "2028-03-02"
  }), { days: 3, interest: 4.93 });
});

test("excludes leap day when it is the end date", function () {
  assert.deepEqual(code.simpleInterest({
    principal: 10000.00,
    annualRate: 0.06,
    startDate: "2028-02-28",
    endDate: "2028-02-29"
  }), { days: 1, interest: 1.64 });
});

test("treats non-leap February as 28 days ending on 28 February", function () {
  assert.deepEqual(code.simpleInterest({
    principal: 10000.00,
    annualRate: 0.06,
    startDate: "2027-02-01",
    endDate: "2027-03-01"
  }), { days: 28, interest: 46.03 });
});

test("returns zero days when start and end are both the leap day", function () {
  assert.deepEqual(code.simpleInterest({
    principal: 10000.00,
    annualRate: 0.06,
    startDate: "2028-02-29",
    endDate: "2028-02-29"
  }), { days: 0, interest: 0.00 });
});

test("calculates interest for a principal and rate other than the sample over 10 days", function () {
  assert.deepEqual(code.simpleInterest({
    principal: 2500.00,
    annualRate: 0.08,
    startDate: "2026-05-01",
    endDate: "2026-05-11"
  }), { days: 10, interest: 5.48 });
});

test("throws when the input has a field other than principal, annualRate, startDate and endDate", function () {
  assert.throws(function () {
    code.simpleInterest({
      principal: 10000.00,
      annualRate: 0.06,
      startDate: "2026-03-01",
      endDate: "2026-04-01",
      extra: 1
    });
  }, /^unknown field: extra$/);
});
